contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint depositAmount) public payable {
        require(address(this).balance >= depositAmount);

        uint256 beforeContractBalance = address(c).balance;
        uint256 beforeTestBalance = c.balances(address(this));

        // drive the public entry point: deposit Ether, then withdraw it
        c.call{value: depositAmount}();
        c.withdraw();

        uint256 afterTestBalance = c.balances(address(this));
        uint256 afterContractBalance = address(c).balance;

        assert(afterTestBalance == 0 && beforeTestBalance + depositAmount == afterContractBalance + beforeContractBalance);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 depositAmount, uint256 withdrawAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient test balance");

        // deposit Ether through the payable fallback to create a positive balance for this test contract
        c.call{value: depositAmount}("");

        // read the before-values for the deciding call
        uint256 beforeTestBal = c.balances(address(this));
        uint256 beforeContractBal = address(c).balance;

        // deciding call: withdraw through the public entry point
        // the amount withdrawn should be exactly the caller's recorded balance
        uint256 expectedWithdrawn = beforeTestBal;

        bool reverted = false;
        try c.withdraw() { reverted = false; } catch { reverted = true; }

        // read after-values
        uint256 afterTestBal = c.balances(address(this));
        uint256 afterContractBal = address(c).balance;

        // general rule: after a successful withdraw, the caller's recorded balance is zero
        // and c's Ether reserve decreases by exactly the withdrawn amount
        // (the withdrawn amount is the caller's recorded balance before the call)
        // if withdraw reverted, the state must be unchanged
        assert(
            (reverted && afterTestBal == beforeTestBal && afterContractBal == beforeContractBal)
            ||
            (!reverted && afterTestBal == 0 && afterContractBal + expectedWithdrawn == beforeContractBal)
        );
    }

    receive() external payable {}
}

