contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 depositAmount, uint256 withdrawAmount) public payable {
        require(depositAmount >= 0);
        require(withdrawAmount >= 0);

        // Deposit Ether to increase our recorded balance.
        require(address(this).balance >= depositAmount);
        (bool depositOk, ) = address(c).call{value: depositAmount}("");
        require(depositOk);

        uint256 recordedBefore = c.balances(address(this));
        uint256 cBalanceBefore = address(c).balance;
        uint256 thisBalanceBefore = address(this).balance;

        // Attempt to withdraw a specific amount from the recorded balance.
        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 recordedAfter = c.balances(address(this));
        uint256 cBalanceAfter = address(c).balance;
        uint256 thisBalanceAfter = address(this).balance;

        // General rule: For any non-zero recorded balance, a withdraw() call should either
        // transfer exactly the recorded balance to the caller and zero the balance, or revert
        // without changing the balance. In all cases, after the call the recorded balance should
        // not remain equal to the original balance while Ether was retained by c.
        if (recordedBefore > 0) {
            if (!reverted) {
                assert(recordedAfter == 0);
                assert(thisBalanceAfter >= thisBalanceBefore + recordedBefore);
                assert(cBalanceAfter + recordedBefore == cBalanceBefore);
            } else {
                assert(recordedAfter == recordedBefore);
                assert(thisBalanceAfter == thisBalanceBefore);
                assert(cBalanceAfter == cBalanceBefore);
            }
        } else {
            // With zero recorded balance, withdraw() should not revert and should change nothing.
            assert(!reverted);
            assert(recordedAfter == 0);
            assert(thisBalanceAfter == thisBalanceBefore);
            assert(cBalanceAfter == cBalanceBefore);
        }
    }

    receive() external payable {}
}

