            ? (
                (reverted == false && balAfter == 0 && cBalAfter == cBalBefore - balBefore)
                || (reverted == true && balAfter == balBefore && cBalAfter == cBalBefore)
            )
            : true
        );
    }

    receive() external payable {}
}

