contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint amount, bool rejectEther) public payable {
        require(amount > 0, "amount must be positive");
        require(msg.value == amount, "must send exactly amount");

        uint256 balBefore = c.balances(address(this));
        uint256 cEthBefore = address(c).balance;

        // Deposit exactly `amount` into c so the caller has a positive recorded balance.
        address(c).call{value: amount}("");

        uint256 balAfterDeposit = c.balances(address(this));
        uint256 cEthAfterDeposit = address(c).balance;

        // Drive the public entry under test.
        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balAfterWithdraw = c.balances(address(this));
        uint256 cEthAfterWithdraw = address(c).balance;

        // The general rule:
        // - A withdraw from a positive recorded balance succeeds iff the caller can receive Ether.
        // - On success, the caller's recorded balance is zero and c's Ether balance decreases by that amount.
        // - On revert, the caller's recorded balance and c's Ether balance are unchanged.
        assert(
            (
                !reverted &&
                balAfterWithdraw == 0 &&
                cEthAfterWithdraw == cEthAfterDeposit - balAfterDeposit
            ) || (
                reverted &&
                balAfterWithdraw == balAfterDeposit &&
                cEthAfterWithdraw == cEthAfterDeposit
            )
        );
    }
}

