                (!reverted && beforeBalance == 0 && afterBalance == 0 && afterContractEth == beforeContractEth)
            );
        } else {
            assert(afterBalance == beforeBalance && afterContractEth == beforeContractEth);
        }
    }

    receive() external payable {}
